import {
  SYNTAX_ACCENT_CHART_FALLBACKS,
  SYNTAX_ACCENT_ORDER,
  SYNTAX_ACCENT_SOURCES,
  SYNTAX_DANGER_SCOPES,
} from "./vscode-theme-sources.mjs";

const ACCENT_MIN_SATURATION = 0.18;

function flattenScopes(scope) {
  if (!scope) return [];
  const raw = Array.isArray(scope) ? scope : [scope];
  return raw.flatMap((entry) => entry.split(/\s+/).filter(Boolean));
}

export function normalizeAccentColor(color) {
  const trimmed = color?.trim();
  if (!trimmed) return undefined;
  if (!trimmed.startsWith("#")) return trimmed;
  const hex = trimmed.slice(1);
  if (hex.length === 3) {
    const expanded = hex
      .split("")
      .map((digit) => digit + digit)
      .join("");
    return `#${expanded.toLowerCase()}`;
  }
  if (hex.length === 6) return `#${hex.toLowerCase()}`;
  if (hex.length === 8) {
    const alpha = Number.parseInt(hex.slice(6, 8), 16);
    if (Number.isNaN(alpha) || alpha < 48) return undefined;
    return `#${hex.slice(0, 6).toLowerCase()}`;
  }
  return undefined;
}

function colorSaturation(hex) {
  const normalized = normalizeAccentColor(hex);
  if (!normalized?.startsWith("#")) return 0;
  const raw = normalized.slice(1);
  if (raw.length !== 6) return 0;
  const r = Number.parseInt(raw.slice(0, 2), 16) / 255;
  const g = Number.parseInt(raw.slice(2, 4), 16) / 255;
  const b = Number.parseInt(raw.slice(4, 6), 16) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  if (max === min) return 0;
  const lightness = (max + min) / 2;
  const delta = max - min;
  return lightness > 0.5 ? delta / (2 - max - min) : delta / (max + min);
}

function isSyntaxAccentCandidate(color, textPrimary) {
  const normalized = normalizeAccentColor(color);
  if (!normalized) return false;
  if (textPrimary && normalized.toLowerCase() === textPrimary.toLowerCase()) return false;
  return colorSaturation(normalized) >= ACCENT_MIN_SATURATION;
}

function scopeMatches(scope, candidate) {
  for (const part of scope.split(/\s+/).filter(Boolean)) {
    if (part === candidate) return { kind: "exact", candidate };
    if (part.startsWith(`${candidate}.`)) return { kind: "prefix", candidate };
  }
  return null;
}

export function pickScopeColorFromTokenColors(tokenColors, candidates, used, textPrimary) {
  const exactHits = [];
  const prefixHits = [];
  for (const entry of tokenColors) {
    const color = normalizeAccentColor(entry.settings?.foreground);
    if (!color || !isSyntaxAccentCandidate(color, textPrimary)) continue;
    const key = color.toLowerCase();
    if (used.has(key)) continue;
    for (const scope of flattenScopes(entry.scope)) {
      for (const candidate of candidates) {
        const match = scopeMatches(scope, candidate);
        if (!match) continue;
        const row = { color, candidate };
        if (match.kind === "exact") exactHits.push(row);
        else prefixHits.push(row);
      }
    }
  }
  for (const candidate of candidates) {
    const hit = exactHits.find((row) => row.candidate === candidate);
    if (hit) return hit.color;
  }
  for (const candidate of candidates) {
    const hit = prefixHits.find((row) => row.candidate === candidate);
    if (hit) return hit.color;
  }
  return undefined;
}

function pickChartColor(colors, keys, used, textPrimary) {
  for (const key of keys) {
    const color = normalizeAccentColor(colors[key]);
    if (!color || !isSyntaxAccentCandidate(color, textPrimary)) continue;
    const normalized = color.toLowerCase();
    if (used.has(normalized)) continue;
    return color;
  }
  return undefined;
}

export function mapSyntaxAccentColors(theme, reservedColors = new Set(), textPrimary) {
  const tokenColors = theme.tokenColors ?? [];
  const colors = theme.colors ?? {};
  const used = new Set(reservedColors);
  const mapped = {};
  const text =
    textPrimary ?? normalizeAccentColor(colors["editor.foreground"] ?? colors["foreground"]);
  for (const token of SYNTAX_ACCENT_ORDER) {
    let color = pickScopeColorFromTokenColors(
      tokenColors,
      SYNTAX_ACCENT_SOURCES[token],
      used,
      text,
    );
    if (!color) {
      color = pickChartColor(colors, SYNTAX_ACCENT_CHART_FALLBACKS[token], used, text);
    }
    if (color) {
      mapped[token] = color;
      used.add(color.toLowerCase());
    }
  }
  return mapped;
}

export function pickSyntaxDangerColor(theme, textPrimary) {
  const colors = theme.colors ?? {};
  const text =
    textPrimary ?? normalizeAccentColor(colors["editor.foreground"] ?? colors["foreground"]);
  return pickScopeColorFromTokenColors(
    theme.tokenColors ?? [],
    SYNTAX_DANGER_SCOPES,
    new Set(),
    text,
  );
}
